      "proposed_laureates": [
        "Maciej Lewenstein",
        "Paul B. Corkum"
      ],
      "assessment": {
        "nobel_worthiness": "Electron recollision made intense-field atomic physics intelligible and opened the route to high-harmonic and attosecond science.",
        "attribution": "Corkum's physical recollision picture and Lewenstein's quantitative strong-field formulation are complementary, central contributions.",
        "maturity": "The mechanism has been tested extensively across atoms, molecules, harmonic generation, and attosecond measurements over decades.",
        "uncertainties": [
          "The contribution is closely interwoven with wider developments in ultrafast laser technology and attosecond metrology."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B056",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks have transformed precision timekeeping while enabling stringent fundamental tests and new measurements.",
        "attribution": "Katori introduced the magic-wavelength lattice-clock concept, while Ye made decisive experimental advances and demonstrations.",
        "maturity": "Independent laboratories now operate clocks at extraordinary accuracy and use them as reliable scientific instruments.",
        "uncertainties": [
          "Credit for the broader optical-clock field extends beyond the two principal names."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B023",
      "proposed_laureates": [
        "Michael V. Berry",
        "Yakir Aharonov"
      ],
      "assessment": {
        "nobel_worthiness": "The Aharonov-Bohm effect and geometric phase changed the physical meaning assigned to phase and have had lasting consequences across quantum physics.",
        "attribution": "Aharonov is essential to the nonlocal phase effect, and Berry identified the general adiabatic geometric phase.",
        "maturity": "Both effects are experimentally established and have become durable conceptual tools in atomic, optical, and condensed-matter physics.",
        "uncertainties": [
          "The two discoveries are related but historically distinct, making the exact framing of a single prize delicate."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B054",
      "proposed_laureates": [
        "Christian J. Bordé",
        "David E. Pritchard",
        "Mark A. Kasevich"
      ],
      "assessment": {
        "nobel_worthiness": "Atom interferometry turned matter-wave coherence into a powerful precision probe of gravity, inertial effects, and fundamental physics.",
        "attribution": "Bordé and Pritchard made foundational conceptual and experimental contributions; Kasevich enabled influential precision implementations.",
        "maturity": "The field has long delivered reproducible precision experiments in many laboratories.",
        "uncertainties": [
          "Its origin and development involve several further indispensable contributors."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B061",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Their proposals established trapped ions and controllable atoms as realistic platforms for quantum computation and simulation.",
        "attribution": "Cirac and Zoller jointly supplied seminal theoretical blueprints linking atomic control to quantum-information tasks.",
        "maturity": "The proposals have been implemented broadly and have shaped a major experimental field.",
        "uncertainties": [
          "The prize case is principally theoretical and overlaps with a larger community of quantum-computing pioneers."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B006",
      "proposed_laureates": [
        "Carlton M. Caves",
        "Nergis Mavalvala",
        "Roman Schnabel"
      ],
      "assessment": {
        "nobel_worthiness": "Squeezed states made it possible to surpass ordinary quantum measurement noise in interferometry, with a direct fundamental and practical impact.",
        "attribution": "Caves articulated the quantum-noise framework, while Mavalvala and Schnabel drove major experimental realization and application.",
        "maturity": "Squeezing is a demonstrated operating resource in large-scale interferometers and laboratory precision measurement.",
        "uncertainties": [
          "The experimental lineage includes important contributions from several groups not represented by these names."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B030",
      "proposed_laureates": [
        "Antoine Browaeys",
        "Mark Saffman",
        "Mikhail Lukin"
      ],
      "assessment": {
        "nobel_worthiness": "Rydberg blockade arrays provide unusually direct control of interacting many-body quantum systems and a compelling route to quantum simulation.",
        "attribution": "Saffman, Browaeys, and Lukin each made central contributions to the blockade concept, its control, and scalable experimental arrays.",
        "maturity": "The platforms now control large programmable arrays and have generated substantial experimental physics.",
        "uncertainties": [
          "The long-term decisive scientific accomplishments of quantum simulation and computing remain in development."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B017",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Tilman Esslinger"
      ],
      "assessment": {
        "nobel_worthiness": "Ultracold atoms in optical lattices made Hubbard-model physics experimentally tunable and directly observable.",
        "attribution": "Bloch, Greiner, and Esslinger made especially influential experimental contributions to establishing this many-body simulator.",
        "maturity": "The approach is mature, widely replicated, and has produced a broad body of quantitative many-body results.",
        "uncertainties": [
          "Theory, proposals, and experiments were developed by a large and closely connected community, complicating a three-person attribution."
        ]
      }
    }
  ]
